export class TouchControls {
 constructor({onAction,onAim,isPlaying}){this.enabled=false;this.axes={moveX:0,moveY:0,lookX:0,lookY:0};this.held=new Set();this.pointers=new Map();this.onAction=onAction;this.onAim=onAim;this.isPlaying=isPlaying;for(const type of ['move','look'])this.bindStick(document.getElementById(type+'-stick'),type);for(const button of document.querySelectorAll('[data-held]'))this.bindButton(button);for(const button of document.querySelectorAll('[data-touch-action]'))button.addEventListener('click',()=>{if(this.enabled&&this.isPlaying())onAction(button.dataset.touchAction);});this.bindSwipe(document.getElementById('space'));}
 setEnabled(value){this.enabled=value;this.clear();document.body.classList.toggle('touch-mode',value);document.getElementById('touch-controls').hidden=!value;}
 clear(){this.held.clear();this.pointers.clear();for(const axis in this.axes)this.axes[axis]=0;for(const el of document.querySelectorAll('.stick-knob'))el.style.transform='translate(-50%,-50%)';for(const el of document.querySelectorAll('[data-held]'))el.classList.remove('pressed');}
 bindStick(el,type){const reset=id=>{const pointer=this.pointers.get(id);if(!pointer||pointer.type!==type)return;this.pointers.delete(id);this.axes[type+'X']=this.axes[type+'Y']=0;el.querySelector('.stick-knob').style.transform='translate(-50%,-50%)';};const update=e=>{const rect=el.getBoundingClientRect(),radius=rect.width*.34;let x=(e.clientX-rect.left-rect.width/2)/radius,y=(e.clientY-rect.top-rect.height/2)/radius;const size=Math.hypot(x,y);if(size>1){x/=size;y/=size;}const dead=n=>Math.abs(n)<.12?0:Math.sign(n)*(Math.abs(n)-.12)/.88;this.axes[type+'X']=dead(x);this.axes[type+'Y']=dead(y);el.querySelector('.stick-knob').style.transform=`translate(calc(-50% + ${x*radius}px),calc(-50% + ${y*radius}px))`;};el.addEventListener('pointerdown',e=>{if(!this.enabled||!this.isPlaying()||[...this.pointers.values()].some(p=>p.type===type))return;e.preventDefault();el.setPointerCapture(e.pointerId);this.pointers.set(e.pointerId,{type});update(e);});el.addEventListener('pointermove',e=>{if(this.pointers.get(e.pointerId)?.type===type){e.preventDefault();update(e);}});for(const event of ['pointerup','pointercancel','lostpointercapture'])el.addEventListener(event,e=>reset(e.pointerId));}
 bindButton(button){const action=button.dataset.held;const release=e=>{if(this.pointers.get(e.pointerId)?.button!==button)return;this.pointers.delete(e.pointerId);this.held.delete(action);button.classList.remove('pressed');if(action==='c')this.onAction('releaseClone');};button.addEventListener('pointerdown',e=>{if(!this.enabled||!this.isPlaying()||[...this.pointers.values()].some(p=>p.button===button))return;e.preventDefault();button.setPointerCapture(e.pointerId);this.pointers.set(e.pointerId,{button});this.held.add(action);button.classList.add('pressed');if(button.dataset.fire)this.onAction(button.dataset.fire);});for(const event of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(event,release);}
 bindSwipe(canvas){canvas.addEventListener('pointerdown',e=>{if(!this.enabled||!this.isPlaying())return;e.preventDefault();canvas.setPointerCapture(e.pointerId);this.pointers.set(e.pointerId,{type:'swipe',x:e.clientX,y:e.clientY});});canvas.addEventListener('pointermove',e=>{const p=this.pointers.get(e.pointerId);if(p?.type!=='swipe'||!this.enabled||!this.isPlaying())return;e.preventDefault();this.onAim((e.clientX-p.x)*.005,(p.y-e.clientY)*.005);p.x=e.clientX;p.y=e.clientY;});for(const event of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(event,e=>{if(this.pointers.get(e.pointerId)?.type==='swipe')this.pointers.delete(e.pointerId);});}
 frame(dt){if(!this.enabled||!this.isPlaying())return {};this.onAim(this.axes.lookX*dt*1.8,-this.axes.lookY*dt*1.5);const input={strafe:this.axes.moveX,throttle:-this.axes.moveY};for(const held of this.held)input[held]=true;return input;}
}
